const tabId = 1148881640;
const details = await browserjs(tabId, () => {
  const currentTempEl = document.querySelector('[data-testid="current-temperature"], .current-weather, [class*="current"]');
  // Let's find all text containing ° or temperature
  const tempElements = Array.from(document.querySelectorAll('*'))
    .filter(el => el.children.length === 0 && el.textContent.includes('°'))
    .map(el => ({ tag: el.tagName, text: el.textContent.trim(), class: el.className, parent: el.parentElement?.className }));

  // Also look for unit switchers (C / F)
  const buttons = Array.from(document.querySelectorAll('button, a, input, [role="button"]'))
    .filter(b => /°C|°F|\bC\b|\bF\b|Celsius|Fahrenheit/i.test(b.textContent) || /unit|temp/i.test(b.getAttribute('aria-label') || ''))
    .map(b => ({ tag: b.tagName, text: b.textContent.trim(), ariaLabel: b.getAttribute('aria-label'), class: b.className }));

  return { tempElements, buttons };
});
console.log(JSON.stringify(details, null, 2));

